//! Runs every case in `test-vectors/coordinate/` against the Rust
//! coordinate/0. The vectors are generated by the independent JavaScript
//! reference (`tools/make-vectors.mjs`), so agreement here means two
//! implementations agree. A case passes when the canonical form of the
//! result, or of the error, equals that of `expect` or `error`, byte for
//! byte (spec section Vector files).
//!
//! The tests read the vectors from disk. The library may not (see
//! `clippy.toml`), so the purity lints are allowed here only.
#![allow(clippy::disallowed_methods, clippy::disallowed_types)]

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

use evidence_coordinate::{extends, factors_value, Dictionary, Error};
use evidence_core::canon::canonicalize;
use evidence_core::json::{self, Value};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../test-vectors/coordinate")
}

fn read(path: &Path) -> Vec<u8> {
    fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn load(name: &str) -> Value {
    let path = root().join(name);
    json::parse(&read(&path)).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn s<'a>(v: &'a Value, key: &str) -> &'a str {
    v.get(key)
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("{key} is not a string in {}", canonicalize(v)))
}

fn finish(kind: &str, failures: Vec<String>, total: usize) {
    assert!(total > 0, "no {kind} vectors found");
    assert!(
        failures.is_empty(),
        "{} of {total} {kind} vectors failed:\n  {}",
        failures.len(),
        failures.join("\n  ")
    );
}

/// Every valid dictionary, by name.
fn dictionaries() -> BTreeMap<String, Dictionary> {
    let index = load("dictionaries.json");
    index
        .get("valid")
        .and_then(Value::as_array)
        .expect("valid cases")
        .iter()
        .map(|c| {
            let name = s(c, "name");
            let path = root().join(format!("dictionaries/valid/{name}.json"));
            let d = Dictionary::parse(&read(&path)).unwrap_or_else(|e| panic!("{name}: {e}"));
            (name.to_string(), d)
        })
        .collect()
}

/// The cases of an operation file, after checking the layout the spec
/// gives: a list of objects, each with a unique `name`, the members `args`,
/// exactly one of `expect` and `error`, and no other member.
fn cases(file: &str, args: &[&str]) -> Vec<Value> {
    let list = load(file);
    let list = list
        .as_array()
        .unwrap_or_else(|| panic!("{file} is not a list"));
    let mut names = BTreeSet::new();
    for c in list {
        let name = s(c, "name");
        assert!(
            names.insert(name.to_string()),
            "{file}: {name} appears twice"
        );
        let members: BTreeSet<&str> = c
            .as_object()
            .unwrap_or_else(|| panic!("{file}: a case is not an object"))
            .iter()
            .map(|(k, _)| k.as_str())
            .collect();
        let outcome = if members.contains("expect") {
            "expect"
        } else {
            "error"
        };
        let want: BTreeSet<&str> = args.iter().copied().chain(["name", outcome]).collect();
        assert_eq!(members, want, "{file}: {name} has other members");
    }
    list.to_vec()
}

/// Compares an operation's outcome with the case's `expect` or `error`.
fn outcome(case: &Value, got: Result<Value, Error>) -> Option<String> {
    let got = match got {
        Ok(v) => ("expect", canonicalize(&v)),
        Err(e) => ("error", canonicalize(&e.to_value())),
    };
    let want = match (case.get("expect"), case.get("error")) {
        (Some(v), None) => ("expect", canonicalize(v)),
        (None, Some(e)) => ("error", canonicalize(e)),
        _ => return Some("needs exactly one of expect and error".to_string()),
    };
    (got != want).then(|| format!("got {} {}, want {} {}", got.0, got.1, want.0, want.1))
}

fn dictionary<'a>(
    all: &'a BTreeMap<String, Dictionary>,
    case: &Value,
    key: &str,
) -> &'a Dictionary {
    let name = s(case, key);
    all.get(name)
        .unwrap_or_else(|| panic!("{}: {name} is not a valid dictionary", s(case, "name")))
}

fn facets(case: &Value) -> Vec<String> {
    case.get("facets")
        .and_then(Value::as_array)
        .unwrap_or_else(|| panic!("{}: facets is not an array", s(case, "name")))
        .iter()
        .map(|f| {
            f.as_str()
                .unwrap_or_else(|| panic!("{}: a facet is not a string", s(case, "name")))
                .to_string()
        })
        .collect()
}

fn arg<'a>(case: &'a Value, key: &str) -> &'a Value {
    case.get(key)
        .unwrap_or_else(|| panic!("{}: no {key}", s(case, "name")))
}

/// The names the spec's case tables require, so that a missing case fails
/// here rather than passing unnoticed.
fn require(file: &str, cases: &[Value], names: &[String]) {
    let have: BTreeSet<&str> = cases.iter().map(|c| s(c, "name")).collect();
    let missing: Vec<&String> = names
        .iter()
        .filter(|n| !have.contains(n.as_str()))
        .collect();
    assert!(
        missing.is_empty(),
        "{file} lacks the spec's cases {missing:?}"
    );
}

fn names(list: &[&str]) -> Vec<String> {
    list.iter().map(|n| n.to_string()).collect()
}

fn numbered(prefix: &str, range: std::ops::RangeInclusive<u32>, width: usize) -> Vec<String> {
    range.map(|i| format!("{prefix}{i:0width$}")).collect()
}

#[test]
fn dictionary_vectors() {
    let index = load("dictionaries.json");
    let members: Vec<&str> = index
        .as_object()
        .expect("an object")
        .iter()
        .map(|(k, _)| k.as_str())
        .collect();
    assert_eq!(
        members.len(),
        2,
        "dictionaries.json has members {members:?}"
    );
    let mut failures = Vec::new();
    let mut total = 0;
    let mut listed: BTreeMap<&str, BTreeSet<String>> = BTreeMap::new();

    for kind in ["valid", "invalid"] {
        for c in index.get(kind).and_then(Value::as_array).expect("a list") {
            total += 1;
            let name = s(c, "name");
            assert!(
                listed.entry(kind).or_default().insert(name.to_string()),
                "{kind}: {name} appears twice"
            );
            let bytes = read(&root().join(format!("dictionaries/{kind}/{name}.json")));
            let got = Dictionary::parse(&bytes);
            let problem = match (kind, got) {
                ("valid", Ok(d)) if d.id() == s(c, "id") => None,
                ("valid", Ok(d)) => Some(format!("id {}, want {}", d.id(), s(c, "id"))),
                ("valid", Err(e)) => Some(format!("rejected with {e}")),
                (_, Ok(d)) => Some(format!("loaded, with id {}", d.id())),
                (_, Err(e)) => {
                    let want = canonicalize(c.get("error").expect("error"));
                    let got = canonicalize(&e.to_value());
                    (got != want).then(|| format!("got {got}, want {want}"))
                }
            };
            if let Some(p) = problem {
                failures.push(format!("{kind} {name}: {p}"));
            }
        }
    }

    // Every file is a case, and every case a file.
    for kind in ["valid", "invalid"] {
        let files: BTreeSet<String> = fs::read_dir(root().join("dictionaries").join(kind))
            .expect("the dictionaries directory")
            .map(|e| {
                e.expect("an entry")
                    .file_name()
                    .into_string()
                    .expect("a UTF-8 name")
            })
            .map(|f| f.strip_suffix(".json").unwrap_or(&f).to_string())
            .collect();
        assert_eq!(
            &files,
            listed.get(kind).unwrap(),
            "{kind} files and cases differ"
        );
    }

    let required_valid = names(&[
        "catalogue-demo",
        "catalogue-demo-reordered",
        "catalogue-demo-v2",
        "catalogue-demo-values-changed",
        "catalogue-demo-prime-changed",
        "catalogue-demo-facet-removed",
        "kernel-2",
        "wide-demo",
        "max-prime-demo",
    ]);
    let required_invalid = names(&[
        "not-json",
        "duplicate-member",
        "number-range",
        "not-an-object",
        "member-missing",
        "member-unknown",
        "prime-not-a-number",
        "shape-before-version",
        "version",
        "version-before-profile",
        "profile",
        "profile-leading-zero",
        "profile-trailing-newline",
        "family-name",
        "family-name-trailing-newline",
        "name-before-values",
        "values",
        "values-before-duplicate",
        "family-duplicate",
        "family-order",
        "families-before-facets",
        "families-before-empty",
        "empty",
        "too-many",
        "id-form",
        "id-form-trailing-newline",
        "checks-within-a-facet",
        "unknown-family",
        "id-duplicate",
        "not-integer",
        "integer-before-range",
        "prime-range-low",
        "prime-range-high",
        "range-before-primality",
        "range-before-order",
        "not-prime",
        "primality-before-order",
        "document-order",
        "prime-duplicate",
        "prime-order",
    ]);
    for (kind, required) in [("valid", required_valid), ("invalid", required_invalid)] {
        let missing: Vec<&String> = required
            .iter()
            .filter(|n| !listed[kind].contains(*n))
            .collect();
        assert!(
            missing.is_empty(),
            "{kind} lacks the spec's cases {missing:?}"
        );
    }
    finish("dictionary", failures, total);
}

#[test]
fn encode_vectors() {
    let all = dictionaries();
    let cases = cases("encode.json", &["dictionary", "facets"]);
    let mut failures = Vec::new();
    for c in &cases {
        let d = dictionary(&all, c, "dictionary");
        let got = d.encode(facets(c)).map(Value::String);
        // Every encode case with `expect` decodes back to its facets.
        if let Ok(Value::String(coordinate)) = &got {
            let back: Vec<String> = d
                .decode(coordinate)
                .expect("an encoded coordinate decodes")
                .into_iter()
                .flat_map(|f| std::iter::repeat_n(f.id, f.exponent as usize))
                .collect();
            let (mut a, mut b) = (back, facets(c));
            a.sort();
            b.sort();
            if a != b {
                failures.push(format!(
                    "{}: does not decode back to its facets",
                    s(c, "name")
                ));
            }
        }
        if let Some(p) = outcome(c, got) {
            failures.push(format!("{}: {p}", s(c, "name")));
        }
    }
    let mut required = names(&[
        "empty",
        "catalogue-example",
        "list-order",
        "set-family",
        "unknown-facet",
        "unknown-facet-trailing-newline",
        "first-unknown-in-list-order",
        "unknown-before-cardinality",
        "one-two-facets",
        "one-repeated",
        "set-repeated",
        "first-family-in-families-order",
        "two-kinds-broken",
        "new-facets",
        "multiset-repeated",
        "first-16-primes",
        "first-20-primes",
        "all-70",
        "2^1023",
        "2^1024",
        "set-family-below-range",
        "set-family-range",
        "cardinality-before-range",
        "below-2^53",
        "above-2^53",
        "below-2^63",
        "above-2^63",
        "below-2^64",
        "above-2^64",
        "max-prime",
    ]);
    required.extend(numbered("section-5-s-e", 1..=5, 1));
    required.extend(numbered("section-5-h-e", 1..=5, 1));
    required.extend(numbered("round-trip-", 1..=100, 3));
    require("encode.json", &cases, &required);
    finish("encode", failures, cases.len());
}

#[test]
fn decode_vectors() {
    let all = dictionaries();
    let cases = cases("decode.json", &["dictionary", "coordinate"]);
    let mut failures = Vec::new();
    for c in &cases {
        let d = dictionary(&all, c, "dictionary");
        let got = d.decode_value(arg(c, "coordinate"));
        // Every decode case with `expect` encodes back to its coordinate.
        if let (Ok(factors), Some(coordinate)) = (&got, arg(c, "coordinate").as_str()) {
            let list: Vec<&str> = factors
                .iter()
                .flat_map(|f| std::iter::repeat_n(f.id.as_str(), f.exponent as usize))
                .collect();
            if d.encode(&list).as_deref() != Ok(coordinate) {
                failures.push(format!("{}: does not encode back", s(c, "name")));
            }
        }
        if let Some(p) = outcome(c, got.map(|f| factors_value(&f))) {
            failures.push(format!("{}: {p}", s(c, "name")));
        }
    }
    let mut required = names(&[
        "one",
        "catalogue-example",
        "syntax-zero",
        "syntax-leading-zero",
        "syntax-plus",
        "syntax-minus",
        "syntax-leading-space",
        "syntax-trailing-space",
        "syntax-trailing-newline",
        "syntax-fraction",
        "syntax-exponent",
        "syntax-empty",
        "syntax-fullwidth-digit",
        "syntax-number",
        "syntax-before-range",
        "syntax-late-in-long-string",
        "unknown-factor",
        "new-facet-under-old-version",
        "unknown-factor-before-cardinality",
        "one-two-facets",
        "one-squared",
        "set-squared",
        "first-family-in-families-order",
        "two-kinds-broken",
        "new-facet",
        "old-coordinate-under-new-version",
        "unclassified-as-a-whole",
        "universal-unclassified",
        "multiset-squared",
        "sqlite-65-bit",
        "sqlite-89-bit",
        "section-5-h-e5",
        "prime-after-dictionary",
        "2^53",
        "2^63",
        "2^64",
        "2^53-minus-1",
        "2^53-plus-1",
        "2^63-minus-1",
        "2^63-plus-1",
        "2^64-minus-1",
        "2^64-plus-1",
        "below-2^53",
        "above-2^53",
        "below-2^63",
        "above-2^63",
        "below-2^64",
        "above-2^64",
        "2^1023",
        "2^1024-minus-1",
        "2^1024",
        "2^1024-plus-1",
        "10^308",
        "2x10^308",
        "309-nines",
        "10^309",
        "set-squared-wide",
        "max-prime",
        "max-prime-squared",
        "unknown-small-factor",
    ]);
    required.extend(numbered("round-trip-", 1..=100, 3));
    require("decode.json", &cases, &required);
    finish("decode", failures, cases.len());
}

#[test]
fn divides_vectors() {
    let all = dictionaries();
    let cases = cases("divides.json", &["dictionary", "query", "coordinate"]);
    let mut failures = Vec::new();
    for c in &cases {
        let d = dictionary(&all, c, "dictionary");
        let got = d.divides_value(arg(c, "query"), arg(c, "coordinate"));
        if let Some(p) = outcome(c, got.map(Value::Bool)) {
            failures.push(format!("{}: {p}", s(c, "name")));
        }
    }
    let required = names(&[
        "one-divides-one",
        "one-divides-everything",
        "query-matches",
        "query-does-not-match",
        "query-equals-coordinate",
        "query-unknown-factor",
        "query-cardinality",
        "query-syntax",
        "query-trailing-newline",
        "coordinate-unknown-factor",
        "coordinate-syntax",
        "coordinate-syntax-late",
        "query-error-first",
        "sqlite-65-bit",
        "sqlite-89-bit",
        "sqlite-65-bit-absent",
        "exponent-short",
        "exponent-enough",
        "past-2^63",
        "past-2^63-reversed",
        "largest",
    ]);
    require("divides.json", &cases, &required);
    finish("divides", failures, cases.len());
}

#[test]
fn check_vectors() {
    let all = dictionaries();
    let cases = cases("check.json", &["dictionary", "facets", "coordinate"]);
    let mut failures = Vec::new();
    for c in &cases {
        let d = dictionary(&all, c, "dictionary");
        let got = d.check_value(facets(c), arg(c, "coordinate"));
        if let Some(p) = outcome(c, got.map(|()| Value::Bool(true))) {
            failures.push(format!("{}: {p}", s(c, "name")));
        }
    }
    let required = names(&[
        "ok",
        "ok-list-order",
        "ok-empty",
        "drift-value",
        "drift-not-canonical",
        "drift-number",
        "drift-unclassified",
        "unknown-facet-first",
        "cardinality-first",
        "range-first",
        "section-5-h-e5",
    ]);
    require("check.json", &cases, &required);
    finish("check", failures, cases.len());
}

#[test]
fn extends_vectors() {
    let all = dictionaries();
    let cases = cases("extends.json", &["old", "new"]);
    let mut failures = Vec::new();
    for c in &cases {
        let old = dictionary(&all, c, "old");
        let new = dictionary(&all, c, "new");
        let got = extends(old, new);
        if let Some(p) = outcome(c, got.map(|()| Value::Bool(true))) {
            failures.push(format!("{}: {p}", s(c, "name")));
        }
    }
    let required = names(&[
        "same",
        "same-reordered",
        "added",
        "family-removed",
        "profile",
        "values-changed",
        "prime-changed",
        "facet-removed",
    ]);
    require("extends.json", &cases, &required);
    finish("extends", failures, cases.len());
}

/// What the spec says of the extends relation, over every pair of valid
/// dictionaries: each extends itself, it is transitive, and when `new`
/// extends `old`, every decode case under `old` decodes the same under
/// `new`.
#[test]
fn extends_relation() {
    let all = dictionaries();
    let decode = cases("decode.json", &["dictionary", "coordinate"]);
    for (a_name, a) in &all {
        assert_eq!(extends(a, a), Ok(()), "{a_name} extends itself");
        for (b_name, b) in &all {
            if extends(a, b).is_err() {
                continue;
            }
            for c in decode.iter().filter(|c| s(c, "dictionary") == a_name) {
                let x = arg(c, "coordinate");
                if let Ok(f) = a.decode_value(x) {
                    assert_eq!(b.decode_value(x), Ok(f), "{} under {b_name}", s(c, "name"));
                }
            }
            for (c_name, c) in &all {
                if extends(b, c).is_ok() {
                    assert_eq!(extends(a, c), Ok(()), "{a_name} < {b_name} < {c_name}");
                }
            }
        }
    }
}
